-- Proposed PostgreSQL schema, not applied or migration-tested.
-- Single organization demo. UUIDs generated by application. Money uses INR only.
CREATE TABLE users (id uuid PRIMARY KEY, subject text UNIQUE NOT NULL, display_name text NOT NULL,
 role text NOT NULL CHECK(role IN ('ANALYST','REVIEWER','MANAGER','AUDITOR','ADMIN')), active boolean NOT NULL DEFAULT true);
CREATE TABLE sources (id uuid PRIMARY KEY, name text UNIQUE NOT NULL, perspective text NOT NULL, timezone text NOT NULL, mapping_version text NOT NULL);
CREATE TABLE scopes (id uuid PRIMARY KEY, source_a uuid NOT NULL REFERENCES sources, source_b uuid NOT NULL REFERENCES sources,
 period_start date NOT NULL, period_end date NOT NULL, currency text NOT NULL CHECK(currency='INR'),
 CHECK(source_a<>source_b), CHECK(period_end>=period_start), UNIQUE(source_a,source_b,period_start,period_end,currency));
CREATE TABLE batches (id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources, idempotency_key text NOT NULL,
 file_sha256 char(64) NOT NULL, raw_object_key text NOT NULL, status text NOT NULL CHECK(status IN ('ACCEPTED','REJECTED')),
 created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(source_id,idempotency_key), UNIQUE(source_id,file_sha256), UNIQUE(id,source_id));
CREATE TABLE transactions (id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources, batch_id uuid NOT NULL,
 source_record_id text NOT NULL, row_number integer NOT NULL CHECK(row_number>=2), reference_raw text NOT NULL,
 reference_normalized text NOT NULL, business_date date NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>0),
 currency text NOT NULL CHECK(currency='INR'), direction text NOT NULL CHECK(direction IN ('CREDIT','DEBIT')),
 payload_sha256 char(64) NOT NULL, FOREIGN KEY(batch_id,source_id) REFERENCES batches(id,source_id),
 UNIQUE(source_id,source_record_id), UNIQUE(batch_id,row_number));
-- Validate precision BEFORE SQL numeric coercion, which could round inputs.
CREATE TABLE matching_rules (id uuid PRIMARY KEY, version text UNIQUE NOT NULL, specification jsonb NOT NULL,
 content_sha256 char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs (id uuid PRIMARY KEY, scope_id uuid NOT NULL REFERENCES scopes, rule_id uuid NOT NULL REFERENCES matching_rules,
 idempotency_key text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','RUNNING','SUCCEEDED','FAILED')),
 input_sha256 char(64), output_sha256 char(64), started_at timestamptz, completed_at timestamptz,
 UNIQUE(scope_id,idempotency_key), UNIQUE(id,scope_id));
CREATE TABLE run_inputs (run_id uuid NOT NULL REFERENCES runs, transaction_id uuid NOT NULL REFERENCES transactions,
 side char(1) NOT NULL CHECK(side IN ('A','B')), PRIMARY KEY(run_id,transaction_id));
CREATE TABLE match_groups (id uuid PRIMARY KEY, run_id uuid NOT NULL, scope_id uuid NOT NULL,
 rule_id uuid NOT NULL REFERENCES matching_rules, FOREIGN KEY(run_id,scope_id) REFERENCES runs(id,scope_id), UNIQUE(id,scope_id));
CREATE TABLE match_members (group_id uuid NOT NULL, scope_id uuid NOT NULL, transaction_id uuid NOT NULL REFERENCES transactions,
 side char(1) NOT NULL CHECK(side IN ('A','B')), PRIMARY KEY(group_id,transaction_id),
 FOREIGN KEY(group_id,scope_id) REFERENCES match_groups(id,scope_id), UNIQUE(scope_id,transaction_id));
-- Service/constraint triggers must enforce source membership, sealed run input,
-- one A + one B for exact-v1 and equal financial fields before publishing a run.
-- Cross-scope overlap must be rejected by service policy under source-pair lock.
CREATE TABLE exceptions (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs, category text NOT NULL,
 severity text NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH')), status text NOT NULL
 CHECK(status IN ('OPEN','IN_REVIEW','PENDING_APPROVAL','ESCALATED','RESOLVED')),
 owner_id uuid REFERENCES users, version integer NOT NULL DEFAULT 1 CHECK(version>0),
 opened_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz, resolved_at timestamptz);
CREATE TABLE exception_transactions (exception_id uuid NOT NULL REFERENCES exceptions, transaction_id uuid NOT NULL REFERENCES transactions,
 PRIMARY KEY(exception_id,transaction_id));
CREATE TABLE investigations (id uuid PRIMARY KEY, exception_id uuid NOT NULL REFERENCES exceptions,
 actor_id uuid NOT NULL REFERENCES users, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence (id uuid PRIMARY KEY, exception_id uuid NOT NULL REFERENCES exceptions, transaction_id uuid REFERENCES transactions,
 object_key text, content_sha256 char(64) NOT NULL, created_by uuid NOT NULL REFERENCES users,
 created_at timestamptz NOT NULL DEFAULT now(), CHECK(transaction_id IS NOT NULL OR object_key IS NOT NULL));
CREATE TABLE recommendations (id uuid PRIMARY KEY, exception_id uuid NOT NULL REFERENCES exceptions, model_version text NOT NULL,
 prompt_version text NOT NULL, output jsonb NOT NULL, verification_status text NOT NULL CHECK(verification_status IN ('PASS','FAIL')),
 trace_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recommendation_evidence (recommendation_id uuid NOT NULL REFERENCES recommendations, evidence_id uuid NOT NULL REFERENCES evidence,
 PRIMARY KEY(recommendation_id,evidence_id));
CREATE TABLE proposals (id uuid PRIMARY KEY, exception_id uuid NOT NULL REFERENCES exceptions, case_version integer NOT NULL,
 proposed_by uuid NOT NULL REFERENCES users, disposition text NOT NULL, rationale text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,proposed_by));
CREATE TABLE proposal_evidence (proposal_id uuid NOT NULL REFERENCES proposals, evidence_id uuid NOT NULL REFERENCES evidence,
 PRIMARY KEY(proposal_id,evidence_id));
CREATE TABLE review_decisions (id uuid PRIMARY KEY, proposal_id uuid UNIQUE NOT NULL, proposed_by uuid NOT NULL,
 reviewed_by uuid NOT NULL REFERENCES users, decision text NOT NULL CHECK(decision IN ('APPROVE','REJECT')),
 rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(proposal_id,proposed_by) REFERENCES proposals(id,proposed_by), CHECK(reviewed_by<>proposed_by));
CREATE TABLE jira_tickets (id uuid PRIMARY KEY, exception_id uuid NOT NULL REFERENCES exceptions, approved_by uuid NOT NULL REFERENCES users,
 external_key text UNIQUE, escalation_key text UNIQUE NOT NULL, remote_status text, synced_at timestamptz);
CREATE TABLE outbox (id uuid PRIMARY KEY, event_key text UNIQUE NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL,
 attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, last_error text);
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, entity_type text NOT NULL,
 entity_id uuid NOT NULL, request_id text NOT NULL, before_state jsonb, after_state jsonb,
 reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX exceptions_worklist ON exceptions(status,severity,due_at);
CREATE INDEX transactions_candidates ON transactions(source_id,reference_normalized,business_date,currency,direction,amount);
CREATE INDEX audit_entity_history ON audit_logs(entity_type,entity_id,created_at);
-- Migration work must create application/migrator roles and deny app updates/deletes
-- on immutable tables. State transitions, actor roles and evidence case ownership
-- require service checks and integration tests; this DDL alone does not enforce them.
